window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-849d538116f2a773"]={"versions": [{"id": "FIG-849d538116f2a773", "releases": ["R4.0.3", "R4.1.3", "R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Matrix- bzw. Metamodellierungs-Architekturdiagramm (OMG MOF 4-Ebenen-Metamodellierungsarchitektur im Vergleich zu technologischen Räumen / Technological Spaces). Das Diagramm ordnet die Ebenen der Modellhierarchie entlang zweier Dimensionen an: Vertikal verläuft die Instanziierungsachse („Instantiiatikn“, von Metaebenen zu realen Objekten), horizontal die Transformationsachse über drei technologische Räume („Metamodel“, „XML“, „TOOL“).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in eine 4x3-Matrix aus Abstraktionsebenen und Technologieräumen:</p>\n<ol class=\"fig-list\"><li><strong>Horizontale Spalten (Technological Spaces):</strong>\n<ul class=\"fig-list\"><li><strong>Metamodel</strong>: Formaler Modellierungsraum auf Basis von MOF/UML.\n</li><li><strong>XML</strong>: Serialisierungs- und Dokumentenraum basierend auf W3C XML Schema.\n</li><li><strong>TOOL</strong>: Werkzeug- und Implementierungsraum (interne Datenstrukturen und Werkzeugmodelle).\n</li></ul>\n</li><li><strong>Vertikale Zeilen (MOF-Abstraktionsebenen):</strong>\n<ul class=\"fig-list\"><li><strong>M3/M4</strong>: Meta-Metamodell-Ebene. Enthält <code>MOF</code> und <code>UML MetaModel</code> in der Metamodell-Spalte sowie <code>XSD-Schema</code> in der XML-Spalte; der TOOL-Raum weist auf dieser Ebene kein Artefakt auf.\n</li><li><strong>M2 Meta-Model</strong>: Standard-Definitionsebene. Enthält <code>AUTOSAR MetaModel</code>, <code>AUTOSAR XML Schema</code> und <code>Tool data structure</code>.\n</li><li><strong>M1 Models</strong>: Systemspezifikations- und Daten-Ebene. Enthält <code>AUTOSAR Model</code>, <code>XML Description</code> (ARXML) und <code>Tool model</code>.\n</li><li><strong>M0 objects</strong>: Reale Laufzeit- bzw. Instanz-Ebene. Enthält <code>AUTOSAR objects</code>, <code>Object in a Car</code> (XML-Spalte) und <code>Object in a Car</code> (TOOL-Spalte).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Relationen:</strong>\n<ul class=\"fig-list\"><li><strong>InstanceOf</strong>: Nach oben gerichtete gerichtete Pfeile mit der Beschriftung <code>InstanceOf</code> verbinden jeweils untergeordnete Elemente mit ihren definierenden Typen/Schemata (M0 -&gt; M1, M1 -&gt; M2, M2 -&gt; M3/M4 sowie innerhalb M3/M4 von UML MetaModel zu MOF).\n</li><li><strong>Transformation</strong>: Horizontale Achse am unteren Bildrand indiziert die Transformation bzw. Abbildung zwischen den Repräsentationen der verschiedenen Technologieräume.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Klassifikationsdiagramm ohne dynamische Laufzeitsequenzen oder Kontrollflüsse. Die Pfeile repräsentieren typisierende Instanziierungsbeziehungen (<code>InstanceOf</code>) von unten nach oben. Die gerichtete Transformationsachse am unteren Rand visualisiert den generativen bzw. transformativen Zusammenhang von der formalen Metamodellspezifikation über XML-Artefakte hin zu internen Tool-Strukturen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild definiert das formale Fundament der AUTOSAR-Interoperabilität. Für Werkzeugentwickler gelten folgende Festlegungen:</p>\n<ul class=\"fig-list\"><li>Das normative <code>AUTOSAR MetaModel</code> (M2) definiert die Struktur des <code>AUTOSAR XML Schema</code> (M2) und bestimmt die Semantik jedes gültigen <code>AUTOSAR Model</code> (M1).\n</li><li>ARXML-Dateien (<code>XML Description</code>, M1) müssen instanziierende Ausprägungen des <code>AUTOSAR XML Schema</code> sein.\n</li><li>Interne Werkzeugdatenstrukturen (<code>Tool data structure</code>, M2) und Werkzeugmodelle (<code>Tool model</code>, M1) müssen konform und verlustfrei auf die entsprechenden M2- und M1-Artefakte des Metamodells bzw. XML-Schemas abbildbar sein, um nahtlosen Datenaustausch zu gewährleisten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-bec945605ccc1269", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Matrix- bzw. Metamodellierungs-Architekturdiagramm (OMG MOF 4-Ebenen-Metamodellierungsarchitektur im Vergleich zu technologischen Räumen / Technological Spaces). Das Diagramm ordnet die Ebenen der Modellhierarchie entlang zweier Dimensionen an: Vertikal verläuft die Instanziierungsachse („Instantiation“, von Metaebenen zu realen Objekten), horizontal die Transformationsachse über drei technologische Räume („Metamodel“, „XML“, „TOOL“).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in eine 4x3-Matrix aus Abstraktionsebenen und Technologieräumen:</p>\n<ol class=\"fig-list\"><li><strong>Horizontale Spalten (Technological Spaces):</strong>\n<ul class=\"fig-list\"><li><strong>Metamodel</strong>: Formaler Modellierungsraum auf Basis von MOF/UML.\n</li><li><strong>XML</strong>: Serialisierungs- und Dokumentenraum basierend auf W3C XML Schema.\n</li><li><strong>TOOL</strong>: Werkzeug- und Implementierungsraum (interne Datenstrukturen und Werkzeugmodelle).\n</li></ul>\n</li><li><strong>Vertikale Zeilen (MOF-Abstraktionsebenen):</strong>\n<ul class=\"fig-list\"><li><strong>M3/M4</strong>: Meta-Metamodell-Ebene. Enthält <code>MOF</code> und <code>UML MetaModel</code> in der Metamodell-Spalte sowie <code>XSD-Schema</code> in der XML-Spalte; der TOOL-Raum weist auf dieser Ebene kein Artefakt auf.\n</li><li><strong>M2 Meta-Model</strong>: Standard-Definitionsebene. Enthält <code>AUTOSAR MetaModel</code>, <code>AUTOSAR XML Schema</code> und <code>Tool data structure</code>.\n</li><li><strong>M1 Models</strong>: Systemspezifikations- und Daten-Ebene. Enthält <code>AUTOSAR Model</code>, <code>XML Description</code> (ARXML) und <code>Tool model</code>.\n</li><li><strong>M0 objects</strong>: Reale Laufzeit- bzw. Instanz-Ebene. Enthält <code>AUTOSAR objects</code>, <code>Object in a Car</code> (XML-Spalte) und <code>Object in a Car</code> (TOOL-Spalte).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Relationen:</strong>\n<ul class=\"fig-list\"><li><strong>InstanceOf</strong>: Nach oben gerichtete gerichtete Pfeile mit der Beschriftung <code>InstanceOf</code> verbinden jeweils untergeordnete Elemente mit ihren definierenden Typen/Schemata (M0 -&gt; M1, M1 -&gt; M2, M2 -&gt; M3/M4 sowie innerhalb M3/M4 von UML MetaModel zu MOF).\n</li><li><strong>Transformation</strong>: Horizontale Achse am unteren Bildrand indiziert die Transformation bzw. Abbildung zwischen den Repräsentationen der verschiedenen Technologieräume.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Klassifikationsdiagramm ohne dynamische Laufzeitsequenzen oder Kontrollflüsse. Die Pfeile repräsentieren typisierende Instanziierungsbeziehungen (<code>InstanceOf</code>) von unten nach oben. Die gerichtete Transformationsachse am unteren Rand visualisiert den generativen bzw. transformativen Zusammenhang von der formalen Metamodellspezifikation über XML-Artefakte hin zu internen Tool-Strukturen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild definiert das formale Fundament der AUTOSAR-Interoperabilität. Für Werkzeugentwickler gelten folgende Festlegungen:</p>\n<ul class=\"fig-list\"><li>Das normative <code>AUTOSAR MetaModel</code> (M2) definiert die Struktur des <code>AUTOSAR XML Schema</code> (M2) und bestimmt die Semantik jedes gültigen <code>AUTOSAR Model</code> (M1).\n</li><li>ARXML-Dateien (<code>XML Description</code>, M1) müssen instanziierende Ausprägungen des <code>AUTOSAR XML Schema</code> sein.\n</li><li>Interne Werkzeugdatenstrukturen (<code>Tool data structure</code>, M2) und Werkzeugmodelle (<code>Tool model</code>, M1) müssen konform und verlustfrei auf die entsprechenden M2- und M1-Artefakte des Metamodells bzw. XML-Schemas abbildbar sein, um nahtlosen Datenaustausch zu gewährleisten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-849d538116f2a773", "to": "FIG-bec945605ccc1269", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Vertikale Achsenbeschriftung: Tippfehler „Instantiiatikn“ korrigiert zu „Instantiation“.\n</li></ul>"}]};
